-- Deities and Demigods: Olympian pantheon divine stat blocks, batch D.
-- Source: Deities and Demigods (2002), Chapter 4, pp. 122-127.
-- Printed 3.0 statistics and source irregularities are preserved; official 3.5 conversion deltas are separate.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('dd-3.0','deities-and-demigods-3-0','Deities and Demigods','DD','Wizards of the Coast','dnd','3.0',
        'Deities and Demigods (2002): divine ranks, pantheons, salient divine abilities, divine minions, domains, spells, monsters, prestige classes, and ascension.',NULL,1,0,NULL);

UPDATE dnd35_deities SET symbol='Lion''s head' WHERE source_id='dd-3.0' AND slug='hercules' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Caduceus (winged staff with two entwining serpents)' WHERE source_id='dd-3.0' AND slug='hermes' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Hearth' WHERE source_id='dd-3.0' AND slug='hestia' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Winged woman' WHERE source_id='dd-3.0' AND slug='nike' AND owner_user_id IS NULL;

WITH desired(slug,name,page,description,mechanics) AS (VALUES
('dd-statblock-hercules','Hercules Divine Stat Block','122-123',
 'Hercules is the divine-rank-5 Olympian demigod of strength and adventure, an ascended mortal without outsider racial Hit Dice.',
 '{"deitySlug":"hercules","pantheon":"olympian","sourceEdition":"3.0","rankBand":"demigod","divineRank":5,"symbol":"Lion''s head","homePlane":"Olympus","alignment":"CG","ascendedMortal":true,"classes":[{"class":"Barbarian","level":20},{"class":"Fighter","level":20}],"creature":{"type":"Outsider","subtypes":["Chaotic","Good"],"size":"Medium","hitDice":"20d12+180 barbarian + 20d10+180 fighter","hitPoints":800,"monsterHitDice":0,"initiative":11,"speed":{"land":70},"armorClass":{"total":44,"dexterity":7,"divine":5,"natural":5,"nemianLionSkin":10,"deflection":7},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"greatclub":"+67/+62/+57/+52 melee, +5 greatclub","greatclubDamage":"1d10+51/19-20","bow":"+53/+48/+43/+38 ranged, +5 mighty distance composite longbow (+4 Str) with +5 arrows","bowDamage":"1d8+14/x3","spellTouch":{"melee":57,"ranged":42}},"saves":{"fort":36,"ref":28,"will":26},"abilities":{"str":55,"dex":25,"con":28,"int":20,"wis":21,"cha":24},"specialQualities":{"printedDamageReduction":"40/+4 (4/-)","printedFireResistance":25,"spellResistance":37,"divineAura":{"radiusFeet":50,"dc":22},"fastMovement":true,"uncannyDodge":"cannot be flanked, +4 against traps","teleportWithoutErrorAtWill":true},"salientDivineAbilities":["Alter Size","Divine Rage","Divine Weapon Focus (greatclub)","Divine Weapon Specialization (greatclub)","Indomitable Strength"],"domainPowers":{"luckRerollUsesPerDay":5,"strengthFeatUsesPerDay":5,"strengthEnhancementBonus":5},"spellLikeAbilities":{"casterLevel":15,"saveDc":"22 + spell level"},"divineRage":{"usesPerDay":5,"duration":"1 hour or until ended","armorClass":39,"hitPoints":1000,"attacks":"greatclub +72/+67/+62/+57, 1d10+56/19-20","fireResistance":35,"spellResistance":47,"saves":{"fort":41,"will":31},"strength":65,"constitution":38},"possessions":{"nemianLionSkin":"Cloak; +10 armor bonus and halves piercing or slashing weapon damage; caster level 20; weight 2 lb."},"automaticActions":{"skills":"Strength- or Dexterity-based skills in which he has ranks or that are usable untrained; simple Strength or Dexterity checks also qualify when not move actions","freeActionDcMaximum":15,"maximumPerRound":5},"avatarStatus":"Hercules does not possess the Avatar salient divine ability in the printed stat block; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":["chaotic","good"],"damageReduction":"15/epic","fireResistance":10,"additionalOutsiderSkillPoints":false,"additionalSkillPointsReason":"Official update explicitly names Hercules among deities with no monster Hit Dice.","barbarian":"Apply revised barbarian class features and rage terminology.","divineRage":"One extra attack at full attack bonus on a full attack rather than an extra partial action.","defunctSkills":["Intuit Direction and Wilderness Lore migrate to revised skills as appropriate"]}}'),

('dd-statblock-hermes','Hermes Divine Stat Block','123-125',
 'Hermes is the divine-rank-15 intermediate Olympian deity of travel, trade, theft, gambling, and running.',
 '{"deitySlug":"hermes","pantheon":"olympian","sourceEdition":"3.0","rankBand":"intermediate","divineRank":15,"titles":["The Master Thief","Messenger of the Gods"],"symbol":"Caduceus (winged staff with two entwining serpents)","homePlane":"Olympus","alignment":"CG","sourceIdentityNote":"Table 4-1 calls the favored weapon Quarterstaff; the individual entry abbreviates this to Staff.","classes":[{"class":"Rogue","level":20},{"class":"Wizard","level":20}],"creature":{"type":"Outsider","subtypes":["Chaotic","Good"],"size":"Large","hitDice":"20d8+140 outsider + 20d6+140 rogue + 20d4+140 wizard","hitPoints":780,"initiative":"+24, always first","speed":{"land":120,"fly":360,"maneuverability":"perfect"},"armorClass":{"total":82,"size":-1,"dexterity":20,"divine":15,"natural":28,"deflection":10},"face":"5 ft. by 5 ft.","reachFeet":10},"attacks":{"primaryStaff":"+64/+64/+59/+54/+49 melee, Huge +5 speed holy quarterstaff","primaryDamage":"1d8+12","secondaryStaff":"+64/+59/+54 melee, Huge +5 defending quarterstaff","secondaryDamage":"1d8+8","spellTouch":{"melee":61,"ranged":74}},"saves":{"fort":54,"ref":67,"will":55,"intermediateDeityChecksAlways20":true},"abilities":{"str":24,"dex":50,"con":24,"int":31,"wis":26,"cha":30},"specialAttacks":{"sneakAttack":"+13d6","cripplingStrike":true},"specialQualities":{"printedDamageReduction":"50/+4","printedFireResistance":null,"sourceFireResistanceNote":"The main Hermes block omits fire resistance even though the avatar prints fire resistance 27 and the generic deity rules normally provide it.","spellResistance":47,"divineAura":{"radiusFeet":1500,"dc":35},"familiar":"birds","rogueFeatures":["evasion","improved evasion","traps","opportunist","slippery mind","uncanny dodge (cannot be flanked, +4 against traps)"],"teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Form","Alter Reality","Alter Size","Arcane Mastery","Avatar","Divine Blast","Divine Celerity","Divine Shield","Divine Dodge","Divine Glibness","Divine Rogue","Divine Sneak Attack","Free Move","Gust of Wind","Supreme Initiative","Extra Domain (Good)","Extra Domain (Luck)","Spontaneous Wizard Spells"],"uniqueAbilities":{"gustOfWind":"Whenever Hermes takes a move action or moves as a free action, he may create light through severe wind extending 150 feet along his path."},"domainPowers":{"chaosSpellsCasterLevelBonus":1,"goodSpellsCasterLevelBonus":1,"luckRerollUsesPerDay":15,"freedomOfMovementRoundsPerDay":15},"spellLikeAbilities":{"casterLevel":25,"chaosAndGoodCasterLevel":26,"saveDc":"35 + spell level"},"spellcasting":{"wizardSpellsPerDay":"4/7/7/6/6/6/6/5/5/5","wizardBaseDc":"20 + spell level"},"possessions":{"caduceus":"Controls animals and beasts as Control Creatures; only functions for divine rank 0+; caster level 25; weight 8 lb."},"automaticActions":{"skills":["Craft (leatherworking)","Disable Device","Knowledge (arcana)","Knowledge (geography)","Knowledge (history)","Knowledge (local)","Knowledge (nobility and royalty)","Knowledge (religion)","Knowledge (the planes)","Open Lock","Profession (guide)","Profession (scribe)","Pick Pocket"],"freeActionDcMaximum":25,"maximumPerRound":10},"avatar":{"divineRank":7,"armorClass":66,"attacks":"speed holy quarterstaff +56/+56/+51/+46/+41 and defending quarterstaff +56/+51/+46","spellTouch":{"melee":53,"ranged":66},"damageReduction":"42/+4","fireResistance":27,"spellResistance":39,"divineAura":{"radiusFeet":700,"dc":27},"saves":{"fort":46,"ref":59,"will":47},"printedSalientDivineAbilities":["Arcane Spell Mastery","Automatic Metamagic (quicken wizard spells)","Divine Dodge","Divine Sneak Attack","Extra Domain (Good)","Extra Domain (Luck)","Gust of Wind","Spontaneous Wizard Spells","Supreme Initiative"],"sourceAbilityNameNote":"The avatar text prints Arcane Spell Mastery while the main block and standard salient ability are Arcane Mastery; the printed wording is preserved.","spellLikeCasterLevel":17,"spellLikeSaveDc":"27 + spell level"},"revision3_5":{"alignmentSubtypes":["chaotic","good"],"damageReduction":"25/epic","fireResistance":20,"additionalOutsiderSkillPoints":true,"rogue":"Additional +2 against traps under revised rogue rules.","divineCelerity":"Functions according to revised haste.","defunctSkills":["Alchemy -> Craft (alchemy)","Intuit Direction migrated","Pick Pocket -> Sleight of Hand","Scry ranks reassigned","Wilderness Lore migrated"]}}'),

('dd-statblock-hestia','Hestia Divine Stat Block','125-126',
 'Hestia is the divine-rank-9 lesser Olympian deity of home, hearth, and family.',
 '{"deitySlug":"hestia","pantheon":"olympian","sourceEdition":"3.0","rankBand":"lesser","divineRank":9,"symbol":"Hearth","homePlane":"Olympus","alignment":"NG","classes":[{"class":"Expert","level":20}],"creature":{"type":"Outsider","subtypes":["Good"],"size":"Large","hitDice":"20d8+160 outsider + 20d6+160 expert","hitPoints":600,"initiative":12,"speed":{"land":80},"armorClass":{"total":58,"size":-1,"dexterity":8,"divine":9,"natural":22,"deflection":10},"face":"5 ft. by 5 ft.","printedReachFeet":5},"attacks":{"dagger":"+55/+50/+45/+40 melee, Small +5 flaming burst dagger","damage":"1d6+17/19-20","spellTouch":{"melee":50,"ranged":46}},"saves":{"fort":39,"ref":39,"will":47},"abilities":{"str":35,"dex":27,"con":27,"int":30,"wis":43,"cha":30},"specialQualities":{"printedDamageReduction":"44/+4","fastHealing":29,"spellResistance":41,"divineAura":{"radiusFeet":900,"dc":29},"extraEnergyImmunity":"fire","teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Form","Alter Reality","Alter Size","Area Divine Shield","Avatar","Divine Blast","Divine Dodge","Divine Fast Healing","Divine Shield","Energy Storm (fire)","Extra Energy Immunity (fire)"],"domainPowers":{"calmEmotionsUsesPerDay":9,"goodSpellsCasterLevelBonus":1,"protectiveWardUsesPerDay":9,"protectiveWardResistanceBonus":9},"spellLikeAbilities":{"casterLevel":19,"goodCasterLevel":20,"saveDc":"29 + spell level"},"portfolioSense":null,"automaticActions":{"skills":["Craft (basketweaving)","Craft (pottery)","Craft (weaving)","Profession (cook)","Profession (farmer)","Profession (herbalist)"],"freeActionDcMaximum":20,"maximumPerRound":5},"avatar":{"divineRank":4,"armorClass":48,"attacks":"dagger +50/+45/+40/+35, 1d6+17 plus 1d6 fire/19-20","spellTouch":{"melee":45,"ranged":41},"damageReduction":"39/+4","spellResistance":36,"divineAura":{"radiusFeet":40,"dc":24},"saves":{"fort":34,"ref":34,"will":42},"salientDivineAbilities":["Alter Size","Divine Dodge","Divine Fast Healing","Divine Shield","Extra Energy Immunity (fire)"],"spellLikeCasterLevel":14,"spellLikeSaveDc":"24 + spell level"},"revision3_5":{"alignmentSubtypes":["good"],"damageReduction":"20/epic","fireResistance":14,"fireImmunityFromSalientAbility":true,"additionalOutsiderSkillPoints":true,"spaceReach":"Use revised Large-creature space/reach numbers as appropriate rather than the printed 5-ft. reach without silently changing the source block.","skillFocus":"Use revised +3 Skill Focus bonus."}}'),

('dd-statblock-nike','Nike Divine Stat Block','126-127',
 'Nike, Goddess of Victory, is a divine-rank-5 Olympian demigod.',
 '{"deitySlug":"nike","pantheon":"olympian","sourceEdition":"3.0","rankBand":"demigod","divineRank":5,"titles":["Goddess of Victory"],"symbol":"Winged woman","homePlane":"Olympus","alignment":"LN","classes":[{"class":"Fighter","level":20},{"class":"Cleric","level":20}],"creature":{"type":"Outsider","size":"Large","hitDice":"20d8+200 outsider + 20d10+200 fighter + 20d8+200 cleric","hitPoints":1120,"initiative":14,"speed":{"land":80,"fly":240,"maneuverability":"perfect"},"armorClass":{"total":56,"size":-1,"dexterity":10,"divine":5,"natural":18,"shield":7,"deflection":7},"face":"5 ft. by 5 ft.","reachFeet":10},"attacks":{"heavyMace":"+66/+61/+56/+51 melee, Large +5 speed lawful wounding heavy mace","damage":"2d6+23","spellTouch":{"melee":60,"ranged":54}},"saves":{"fort":47,"ref":47,"will":44},"abilities":{"str":42,"dex":31,"con":30,"int":24,"wis":24,"cha":24},"specialQualities":{"printedDamageReduction":"40/+4","printedFireResistance":25,"spellResistance":37,"divineAura":{"radiusFeet":50,"dc":22},"teleportWithoutErrorAtWill":true},"salientDivineAbilities":["Alter Form","Alter Size","Annihilating Strike","Divine Battle Mastery","Divine Inspiration (dread)","Sunder and Disjoin"],"domainPowers":{"lawSpellsCasterLevelBonus":1,"nobilityInspireAlliesUsesPerDay":5,"nobilityMoraleBonus":2,"nobilityDurationRounds":7},"spellLikeAbilities":{"casterLevel":15,"lawCasterLevel":16,"saveDc":"22 + spell level"},"spellcasting":{"clericSpellsPerDay":"6/8/8/8/7/7/6/6/5/5","clericBaseDc":"17 + spell level"},"automaticActions":{"skills":["Craft (armorsmithing)","Craft (bowmaking)","Craft (weaponsmithing)","Knowledge (arcana)","Knowledge (history)","Knowledge (nobility and royalty)","Knowledge (religion)","Profession (lawyer)"],"freeActionDcMaximum":15,"maximumPerRound":5},"avatarStatus":"Nike does not possess the Avatar salient divine ability in the printed stat block; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":["lawful"],"damageReduction":"15/epic","fireResistance":10,"additionalOutsiderSkillPoints":true,"divineInspirationDread":"Use the revised crushing-despair-style -4 penalty for the despair/dread aspect where applicable.","defunctFeat":"Improved Sunder is obsolete in the update and should use the revised Improved Sunder treatment.","defunctSkills":["Scry ranks reassigned"]}}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,
   category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT
  'dd-rule-'||d.slug,'dd-3.0',d.page,d.slug,d.name,d.description,
  'Use the structured mechanics payload for the printed Deities and Demigods divine stat block. Printed 3.0 values remain source-of-truth; revision3_5 records official conversion deltas and source notes preserve printed irregularities.',
  0,NULL,1,'deity','divine-stat-block',0,1,'dd-olympian-pantheon',NULL,
  '["deities-and-demigods","olympian","deity-stat-block","revision-3.5"]',
  d.mechanics
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_rules r WHERE r.source_id='dd-3.0' AND r.slug=d.slug AND r.owner_user_id IS NULL
);
